package cz.kamenitxan.jakon.shop.it

import cz.kamenitxan.jakon.core.configuration.Settings
import cz.kamenitxan.jakon.shop.pages.{CategoryListPage, IndexPage, ProductPage}
import org.scalatest.DoNotDiscover
import org.scalatest.funsuite.AnyFunSuite

import java.io.File

/** Static pages generated by the shop. */
@DoNotDiscover
class ShopPagesTest extends AnyFunSuite with ShopDbSupport {

	private def outputFile(name: String) = new File(Settings.getOutputDir, name)

	test("IndexPage renders product list") {
		new IndexPage().generateRun()
		assert(outputFile("index.html").exists())
	}

	test("ProductPage renders detail of every product including variants") {
		val variant = createVariant("Velikost")
		createVariantValue(variant, "M")
		val category = createCategory()
		withConn(conn => {
			val stmt = conn.prepareStatement("INSERT INTO ShopCategoryProductVariant (shopCategory_id, productVariant_id) VALUES (?, ?)")
			stmt.setInt(1, category.id)
			stmt.setInt(2, variant.id)
			stmt.executeUpdate()
			stmt.close()
		})
		val withCategory = createProduct(category = category)
		val withoutCategory = createProduct()

		new ProductPage().generateRun()

		assert(outputFile(s"product${withCategory.id}.html").exists())
		assert(outputFile(s"product${withoutCategory.id}.html").exists())
	}

	test("CategoryListPage renders every category") {
		val category = createCategory()
		new CategoryListPage().generateRun()
		assert(new File(Settings.getOutputDir).listFiles().nonEmpty)
		assert(category.createUrl.nonEmpty)
	}
}
